  @override
  String get faqMyDayA =>
      'ದಿನಕ್ಕೆ ಒಮ್ಮೆ ಮುಖಪುಟ ಇದನ್ನು ನೀಡುತ್ತದೆ: ಇಂದಿನ ಕಾರ್ಯಗಳು, ಮುಂದಿನ ಈವೆಂಟ್, ಬಾಕಿ ಅಭ್ಯಾಸಗಳು ಮತ್ತು ಬಾಕಿ ಕಾರ್ಡ್‌ಗಳನ್ನು ನೋಡಿ, ನಂತರ ಒಂದು ಟ್ಯಾಪ್‌ನಲ್ಲಿ ಫೋಕಸ್ ಸೆಷನ್ ಪ್ರಾರಂಭಿಸಿ. ತ್ವರಿತ ಕ್ರಿಯೆಗಳಿಗಾಗಿ ಆ್ಯಪ್ ಐಕಾನ್ ಅನ್ನು ದೀರ್ಘವಾಗಿ ಒತ್ತಿ, ಅಥವಾ ಫೋಕಸ್ ಸಮಯ ಮತ್ತು ಬಾಕಿ ಕಾರ್ಡ್‌ಗಳನ್ನು ನೋಡಲು ಮುಖಪುಟ ವಿಜೆಟ್ ಸೇರಿಸಿ.';

