  @override
  String get faqSoundsA =>
      'ಆರು ನೈಜ ರೆಕಾರ್ಡಿಂಗ್‌ಗಳವರೆಗೆ ಆನ್ ಮಾಡಿ, ಪ್ರತಿಯೊಂದರ ಧ್ವನಿಮಟ್ಟ ಹೊಂದಿಸಿ ಮತ್ತು ಮಿಶ್ರಣವನ್ನು ಹೆಸರಿನೊಂದಿಗೆ ಉಳಿಸಿ. ಅವು ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಪ್ಲೇ ಆಗುತ್ತಲೇ ಇರುತ್ತವೆ, ಮತ್ತು ನಿದ್ರಾ ಟೈಮರ್ ಅವುಗಳನ್ನು ನಿಲ್ಲಿಸಬಹುದು. ಯಾವುದೇ ಸಂಗೀತ ಬಳಸಲಾಗುವುದಿಲ್ಲ.';

