  @override
  String get faqCalendarA =>
      'ಹೌದು. ಹಿಜ್ರಿ ದಿನಾಂಕಗಳು (ಉಮ್ಮುಲ್ ಕುರಾ) ಅರೇಬಿಕ್‌ನಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಕಾಣಿಸುತ್ತವೆ ಮತ್ತು ಯಾವುದೇ ಭಾಷೆಗೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಆನ್ ಮಾಡಬಹುದು. ಈವೆಂಟ್‌ಗಳು, ಕೊನೆಯ ದಿನಾಂಕವಿರುವ ಕಾರ್ಯಗಳು ಮತ್ತು ಪ್ರಾಜೆಕ್ಟ್ ಮೈಲಿಗಲ್ಲುಗಳು ಒಟ್ಟಿಗೆ ಕಾಣಿಸುತ್ತವೆ.';

