  @override
  String get faqFlashcardsA =>
      'ನಿಮಗೆ ಚೆನ್ನಾಗಿ ಗೊತ್ತಿರುವ ಕಾರ್ಡ್‌ಗಳು ದೀರ್ಘ ಅಂತರದ ನಂತರ ಮರಳುತ್ತವೆ ಮತ್ತು ತಪ್ಪಿದ ಕಾರ್ಡ್‌ಗಳು ಬೇಗ ಮರಳುತ್ತವೆ (ಅಂತರದ ಪುನರಾವರ್ತನೆ). ಪ್ರತಿ ಉತ್ತರಕ್ಕೆ ಮತ್ತೆ, ಕಷ್ಟ, ಒಳ್ಳೆಯದು ಅಥವಾ ಸುಲಭ ಎಂದು ರೇಟ್ ಮಾಡಿ. ದೈನಂದಿನ ಗುರಿ ಹೊಂದಿಸಿ ಮತ್ತು ಇಂದು ಕಾರ್ಡ್‌ನಲ್ಲಿ ನಿಮ್ಮ ಸರಣಿ ಉಳಿಸಿಕೊಳ್ಳಿ. ಉಳಿದ ದಿನಗಳು ಮತ್ತು ಪ್ರತಿದಿನ ಎಷ್ಟು ಹೊಸ ಕಾರ್ಡ್ ಕಲಿಯಬೇಕು ಎಂದು ನೋಡಲು ಡೆಕ್‌ನಲ್ಲಿ ಪರೀಕ್ಷಾ ದಿನಾಂಕ ಹೊಂದಿಸಿ. ಕಾರ್ಡ್‌ಗಳನ್ನು ಸ್ಥಾನಕ್ಕೆ ಎಳೆಯಲು \"ನನ್ನ ಕ್ರಮ\" ಪ್ರಕಾರ ವಿಂಗಡಿಸಿ, ಕೇಳಲು ಯಾವುದೇ ಬದಿಯ ಸ್ಪೀಕರ್ ಟ್ಯಾಪ್ ಮಾಡಿ, ಮತ್ತು ಮಾತು ಮೆನುವಿನಲ್ಲಿ ವೇಗ ಮತ್ತು ಪುನರಾವರ್ತನೆ ಹೊಂದಿಸಿ.';

