  @override
  String get faqImportA =>
      'ಹೌದು. ಡೆಕ್‌ನಲ್ಲಿ ಆಮದು ಆಯ್ಕೆಮಾಡಿ, ನಂತರ ಫೈಲ್ ಆರಿಸಿ: Anki (.apkg), Excel (.xlsx) ಅಥವಾ CSV, ಮತ್ತು ಕಾಲಮ್‌ಗಳನ್ನು ಹೊಂದಿಸಿ. ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಕಾರ್ಡ್ ಬರೆಯಲು “ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಟೆಂಪ್ಲೇಟ್” ಬಳಸಿ. Anki ಫೈಲ್‌ಗಳ ಒಳಗಿನ ಚಿತ್ರಗಳು ಮತ್ತು ಧ್ವನಿಗಳನ್ನು ಆಮದು ಮಾಡಲಾಗುವುದಿಲ್ಲ.';

  @override
  String get faqNotesQ => 'ಟಿಪ್ಪಣಿಗಳು ಏನು ಮಾಡಬಲ್ಲವು?';

  @override
  String get faqNotesA =>
      'ಪರಿಶೀಲನಾ ಪಟ್ಟಿಗಳು ಮತ್ತು ಫಾರ್ಮ್ಯಾಟಿಂಗ್‌ನೊಂದಿಗೆ ಮುಕ್ತವಾಗಿ ಬರೆಯಿರಿ, ಮುಖ್ಯ ಟಿಪ್ಪಣಿಗಳನ್ನು ಪಿನ್ ಅಥವಾ ಮೆಚ್ಚಿನದು ಮಾಡಿ, ಟ್ಯಾಗ್‌ಗಳನ್ನು ಸೇರಿಸಿ ಮತ್ತು ಟಿಪ್ಪಣಿಗಳನ್ನು ಕಾರ್ಯಗಳಿಗೆ ಲಿಂಕ್ ಮಾಡಿ. ಮೈಕ್ರೊಫೋನ್ ಬಟನ್ ಡಿಕ್ಟೇಟ್ ಮಾಡಲು ಅನುಮತಿಸುತ್ತದೆ. ಹೊಸ ಟಿಪ್ಪಣಿ ಟೆಂಪ್ಲೇಟ್‌ನಿಂದ (ಉಪನ್ಯಾಸ, ಪುಸ್ತಕ ಸಾರಾಂಶ, ದಿನಚರಿ, ವಾರದ ಯೋಜನೆ) ಪ್ರಾರಂಭವಾಗಬಹುದು, ಮತ್ತು ಚಿತ್ರ ಬಟನ್ ಫೋಟೋಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ.';

