  @override
  String get faqGuardA =>
      'ಫೋಕಸ್ → ಟೈಮರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಗಮನಭಂಗ ರಕ್ಷಕ ತೆರೆಯಿರಿ. ಆ್ಯಪ್‌ಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ, ನಂತರ ಸೌಮ್ಯ (5 ಸೆಕೆಂಡುಗಳ ಉಸಿರು ಮತ್ತು \"ನಿಮಗೆ ಈಗ ಈ ಆ್ಯಪ್ ಬೇಕೇ?\" ಎಂಬ ಪ್ರಶ್ನೆ) ಅಥವಾ ಕಟ್ಟುನಿಟ್ಟಾದ (ಅವು ಮುಚ್ಚಿರುತ್ತವೆ). ಇದು ಫೋಕಸ್ ಸೆಷನ್‌ಗಳಲ್ಲಿ ಮತ್ತು, ಸಮಯ ರಕ್ಷಕದೊಂದಿಗೆ, ನೀವು ಹೊಂದಿಸಿದ ದಿನಗಳು ಮತ್ತು ಗಂಟೆಗಳಲ್ಲಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ. \"ಆಯ್ಕೆಮಾಡಿದ ಆ್ಯಪ್‌ಗಳನ್ನು ಮಾತ್ರ ಅನುಮತಿಸಿ\" ಉಳಿದೆಲ್ಲವನ್ನೂ ವಿರಾಮಗೊಳಿಸುತ್ತದೆ; ಕರೆಗಳು, ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಕೀಬೋರ್ಡ್ ಯಾವಾಗಲೂ ಕೆಲಸ ಮಾಡುತ್ತವೆ. ಪ್ರವೇಶಿಸುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ರಕ್ಷಕವನ್ನು ಆನ್ ಮಾಡಲು Android ಒಮ್ಮೆ ಕೇಳುತ್ತದೆ. ಇದು ಯಾವ ಆ್ಯಪ್ ತೆರೆದಿದೆ ಎಂದು ಮಾತ್ರ ನೋಡುತ್ತದೆ ಮತ್ತು ಏನನ್ನೂ ಕಳುಹಿಸುವುದಿಲ್ಲ.';

